use std::{fs,path::Path};
fn main(){let root=Path::new("/tmp/zopro-front-snapshot-fence");let old=fs::read_to_string("/tmp/zopro-serial-fft-leaves/make-protocol.rs").unwrap();let mut source=old.replace("/tmp/zopro-serial-fft-leaves","/tmp/zopro-front-snapshot-fence").replace("candidate-v2/","candidate/").replace("native-v2/","native/").replace("ZOPRO_CPU_SERIAL_FFT_LEAVES","ZOPRO_CPU_FRONT_SNAPSHOT_FENCE");let start=source.find("for name in [\"experiment.json\"").unwrap();let end=source[start..].find("\nadd_file(\"/home/ubuntu").unwrap()+start;source.replace_range(start..end,r#"for name in ["experiment.json","prepare.json","native-plan.json","source-audit.rs","source-audit.json","ordering-review.md","implement.rs","prepare-build.rs","make-protocol.rs","prepare-protocol-source.rs","analyze.rs","analyze","analyze-tests","analyze-tests.log","inventory-preflight.sh","validate-preflight.jq","build-input-pins.json","upstream-pins.json","lock-audit.json","registry-audit.rs","registry-audit.json","registry-input-pins.json","research/source-pins.json","research/notes.md"]{add_file(root.join(name),&mut pins)}
for file in ["build-input-pins.json","registry-input-pins.json","research/source-pins.json"] {for(name,digest)in read(root.join(file)).as_object().unwrap(){assert_eq!(hash(name),digest.as_str().unwrap());pins.insert(name.clone(),digest.as_str().unwrap().into());}}
let mut linked=serde_json::Map::new();for(variant,path)in [("accepted","/tmp/zopro-grouping-module/native/libraries/stdout.log"),("candidate","/tmp/zopro-front-snapshot-fence/native/libraries/stdout.log")]{let text=fs::read_to_string(path).unwrap();let mut found=BTreeMap::<String,String>::new();for line in text.lines(){if let Ok(v)=serde_json::from_str::<Value>(line){if v["reason"]=="compiler-artifact"{if let Some(name)=v["target"]["name"].as_str(){if ["crossbeam_deque","crossbeam_epoch","crossbeam_utils","rayon_core"].contains(&name){for f in v["filenames"].as_array().unwrap(){let p=f.as_str().unwrap();if p.ends_with(".rlib"){assert!(found.insert(name.into(),p.into()).is_none());add_file(p,&mut pins);}}}}}}}assert_eq!(found.len(),4);linked.insert(variant.into(),json!(found));add_file(path,&mut pins);}save(root.join("linked-scheduler-libraries.json"),json!(linked));add_file(root.join("linked-scheduler-libraries.json"),&mut pins);"#);
let marker="inventory(\"/tmp/zopro-fft-pass-grain/proof-inventory.json\",&mut prior);";assert_eq!(source.matches(marker).count(),1);source=source.replace(marker,&format!("{marker}\ninventory(\"/tmp/zopro-serial-fft-leaves/proof-inventory.json\",&mut prior);\ninventory(\"/tmp/zopro-retained-deque-buffers/proof-inventory.json\",&mut prior);"));
fs::write(root.join("make-protocol.rs"),source).unwrap();for name in ["analyze.rs","inventory-preflight.sh","validate-preflight.jq"]{let text=fs::read_to_string(Path::new("/tmp/zopro-serial-fft-leaves").join(name)).unwrap().replace("/tmp/zopro-serial-fft-leaves","/tmp/zopro-front-snapshot-fence");fs::write(root.join(name),text).unwrap();}println!("Prepared fixed full-nine protocol source and prior-identity union");}
